_table: dict[str, str] = {}


def set_language(code: str) -> None:
    global _table
    _table = {}
    if code in T:
        tr_list = T[code].split("|")
        if len(tr_list) == len(EN):
            _table = dict(zip(EN, tr_list))


def tr(text: str) -> str:
    if not _table or not text:
        return text
    core = text.strip()
    if core in _table:
        return text.replace(core, _table[core])
    return text


def apply(widget) -> None:
    """Translates a window and everything in it."""
    if not _table:
        return
    try:
        if widget.winfo_class() == "TNotebook":
            for tab in widget.tabs():
                t = widget.tab(tab, "text")
                head, dot, name = t.partition(". ")
                if dot:
                    widget.tab(tab, text=f"{head}. {tr(name.strip())}  ")
                else:
                    widget.tab(tab, text=tr(t))
        else:
            t = widget.cget("text")
            if isinstance(t, str) and t:
                n = tr(t)
                if n != t:
                    widget.configure(text=n)
    except (tk.TclError, AttributeError):
        pass
    for child in widget.winfo_children():
        apply(child)
